// C# İki Sayının Toplamı Algoritması
int sayi1 = 15;
int sayi2 = 25;
int toplam = sayi1 + sayi2;
Console.WriteLine("Toplam: " + toplam);

int ogrenciYasi = 20;
double dersOrtalamasi = 3.45;
string ogrenciAdi = "Ayşe Yılmaz";
bool kayitAktifMi = true;
char harfNotu = 'A';

Console.WriteLine($"Öğrenci: {ogrenciAdi}, Ort: {dersOrtalamasi}");

int sayi = 17;
bool ciftMi = (sayi % 2 == 0);

int vize = 60;
int finalNotu = 70;
bool gectiMi = (vize * 0.4 + finalNotu * 0.6 >= 60) && (finalNotu >= 50);

Console.WriteLine($"Çift mi: {ciftMi}, Geçti mi: {gectiMi}");

// if-else yapısı
int bakiye = 500;
int cekilmekIstenen = 750;

if (cekilmekIstenen <= bakiye)
{
    bakiye -= cekilmekIstenen;
    Console.WriteLine("Para çekildi.");
}
else
{
    Console.WriteLine("Yetersiz Bakiye!");
}

// switch-case yapısı
int gunNo = 3;
switch (gunNo)
{
    case 1: Console.WriteLine("Pazartesi"); break;
    case 2: Console.WriteLine("Salı"); break;
    case 3: Console.WriteLine("Çarşamba"); break;
    default: Console.WriteLine("Geçersiz Gün"); break;
}

// 1'den 10'a kadar olan çift sayıları yazdırma
for (int i = 1; i <= 10; i++)
{
    if (i % 2 == 0)
    {
        Console.WriteLine("Çift sayı: " + i);
    }
}

// While ile şifre doğrulama
string sifre = "";
while (sifre != "1234")
{
    Console.Write("Şifreyi giriniz: ");
    sifre = Console.ReadLine();
}

int[] notlar = new int[] { 85, 90, 70, 100, 60 };

// Elemana erişim ve değiştirme
Console.WriteLine("İlk not: " + notlar[0]); // 85
notlar[2] = 75; // 70 olan 3. elemanı 75 yaptık

// Diziyi döngüyle gezme
int toplam = 0;
for (int i = 0; i < notlar.Length; i++)
{
    toplam += notlar[i];
}
double ortalama = (double)toplam / notlar.Length;
Console.WriteLine("Sınıf Ortalaması: " + ortalama);

// Geriye değer döndürmeyen metot (void)
static void Selamla(string isim)
{
    Console.WriteLine($"Merhaba {isim}, hoş geldin!");
}

// Geriye değer döndüren metot (int)
static int Topla(int sayi1, int sayi2)
{
    return sayi1 + sayi2;
}

// Metotların çağrılması
Selamla("Ahmet");
int sonuc = Topla(25, 40);
Console.WriteLine("Sonuç: " + sonuc);
